function r3(x) { return Math.round(x * 1000) / 1000; }
function rec(rows) {
  var tp = 0, fn = 0;
  rows.forEach(function (r) { if (r.actual && r.predicted) tp++; else if (r.actual) fn++; });
  return { v: tp + fn ? tp / (tp + fn) : 0, pos: tp + fn };
}

function evaluate(results, req) {
  var tp = 0, fp = 0;
  results.forEach(function (r) { if (r.predicted && r.actual) tp++; else if (r.predicted) fp++; });
  var precision = r3(tp + fp ? tp / (tp + fp) : 0);
  var all = rec(results), recall = r3(all.v);
  var groups = {}, groupRecall = {};
  results.forEach(function (r) { (groups[r.group] = groups[r.group] || []).push(r); });
  var fairOk = true;
  Object.keys(groups).forEach(function (g) {
    var x = rec(groups[g]);
    groupRecall[g] = r3(x.v);
    if (x.pos > 0 && r3(Math.abs(groupRecall[g] - recall)) > req.maxGap) fairOk = false;
  });
  var passed = [], failed = [];
  [['MP-1', precision >= req.minPrecision], ['MP-2', recall >= req.minRecall], ['FR-1', fairOk]].forEach(function (c) { (c[1] ? passed : failed).push(c[0]); });
  return { precision: precision, recall: recall, groupRecall: groupRecall, passed: passed, failed: failed };
}

